SELECT p.gender, AVG(d.risk_score) AS average_risk_score, cume_dist() OVER (ORDER BY d.risk_score) AS percentile_rank, COUNT(CASE WHEN d.death_date <= d.admit_date + INTERVAL '90 days' THEN 1 END) AS deaths_in_90_days, SUM(CASE WHEN d.vent_ac_kind = 'A' THEN 1 ELSE 0 END) AS aki_count, SUM(CASE WHEN d.vent_ac_kind = 'R' THEN 1 ELSE 0 END) AS ards_count, AVG(d.length_of_stay) AS average_length_of_stay FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id WHERE p.gender = 'M' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) = 86 AND p.anchor_year BETWEEN 81 AND 91 AND d.icd_code = '448.91' AND d.icd_version = '2015' AND d.risk_score > (SELECT percentile_cont(0.75) within GROUP (ORDER BY risk_score) FROM diagnoses_icd) GROUP BY p.gender;